CREATE TRIGGER RefMRComponentCode_Version_Create
	ON RefMRComponentCode
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RCC_PK, 'RCC'
	FROM inserted
GO
CREATE TRIGGER RefMRComponentCode_Version_Update
	ON RefMRComponentCode
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RCC_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
